-- AUTOGENERATED HYPRLAND CONFIG, converted from hyprland.conf to hyprland.lua
-- ###############################################################################
--
-- You can split this configuration into multiple files with require():
--   require("myColors")  -- looks for myColors.lua next to this file
--
-- Notes on this conversion:
--   * A few dispatchers below (mouse move/resize binds, master-layout dispatchers
--     like orientationnext/swapwithmaster) don't have a fully published Lua
--     signature as of this writing. They're marked with -- VERIFY comments.
--     Use `hyprctl` / the Lua LSP stubs to confirm the exact field names before
--     you trust them blind.

----------------
---- MONITORS ---
----------------

-- See https://wiki.hypr.land/Configuring/Monitors/
hl.monitor({ output = "DP-2",    mode = "1920x1080@144", position = "0x0",    scale = 1 })
hl.monitor({ output = "HDMI-A-1", mode = "1920x1080@60", position = "1920x0", scale = 1 })

hl.workspace_rule({ workspace = 1, monitor = "DP-2" })
hl.workspace_rule({ workspace = 2, monitor = "HDMI-A-1" })
hl.workspace_rule({ workspace = 3, monitor = "DP-2" })
hl.workspace_rule({ workspace = 4, monitor = "HDMI-A-1" })

------------------
---- MY PROGRAMS --
------------------

-- Plain Lua locals replace the old $variables
local terminal    = "kitty"
local fileManager  = "dolphin"
local menu         = "noctalia msg panel-toggle launcher"
local browser      = "librewolf"

-----------------
---- AUTOSTART ---
-----------------

-- exec-once -> run once, at compositor start
hl.on("hyprland.start", function()
  hl.dsp.exec_cmd("noctalia")
  hl.dsp.exec_cmd("hyprctl setcursor breeze_cursors 24")
  hl.dsp.exec_cmd("gsettings set org.gnome.desktop.interface cursor-theme 'breeze_cursors'")
  hl.dsp.exec_cmd("gsettings set org.gnome.desktop.interface cursor-size 24")
end)

